import React, { Component } from "react";
import "./Login.css";

export default class Login extends Component {
    constructor(props) {
        super(props);
        this.state = {
            activeTab: 'signup',
            formData: {},
            buttonsdata: [],
            leftside: [],
            rightside: [],
            loginFormData: {},
            loginButtonsdata: [],
            loginText: [],
            loginImages: {},
            signupImages: {}
        };
    }

    componentDidMount() {
        fetch('http://localhost:3001/Signup')
            .then(response => response.json())
            .then(data => {
                this.setState({
                    formData: this.buildInitialFormData(data.content.text),
                    buttonsdata: data.content.buttons,
                    leftside: data.content.text.leftside,
                    rightside: data.content.text.rightside,
                    signupImages: { img1: data.img1, img2: data.img2 }
                });
            })
            .catch(error => console.error('Error fetching signup data:', error));

        fetch('http://localhost:3001/Login')
            .then(response => response.json())
            .then(data => {
                this.setState({
                    loginFormData: this.buildInitialFormData(data.content.text),
                    loginButtonsdata: data.content.buttons,
                    loginText: data.content.text,
                    loginImages: { img1: data.img1, img2: data.img2 }
                });
            })
            .catch(error => console.error('Error fetching login data:', error));
    }

    buildInitialFormData = (text) => {
        const initialFormData = {};
        if (Array.isArray(text)) {
            text.forEach(field => {
                initialFormData[field.placeholder.replace(/ /g, '').toLowerCase()] = field.value;
            });
        } else {
            [...text.leftside, ...text.rightside].forEach(field => {
                initialFormData[field.placeholder.replace(/ /g, '').toLowerCase()] = field.value;
            });
        }
        return initialFormData;
    };

    setActiveTab = (tab) => {
        this.setState({ activeTab: tab });
    };

    render() {
        const { activeTab, formData, buttonsdata, leftside, rightside, loginFormData, loginButtonsdata, loginText, loginImages, signupImages } = this.state;

        return (
            <div className="content-container">
                <div className="formboxx">
                    <div className="button-boxx">
                        <div id="btn"></div>
                        {buttonsdata.map((value, index) => (
                            <button
                                key={index}
                                type={value.type}
                                className={activeTab === value.text ? 'active' : ''}
                                onClick={() => this.setActiveTab(value.text)}
                            >
                                {value.text}
                            </button>
                        ))}
                    </div>

                    <div className="social-icons">
                        <img src={activeTab === 'signup' ? signupImages.img1 : loginImages.img1} alt="social icon 1" />
                        <img src={activeTab === 'signup' ? signupImages.img2 : loginImages.img2} alt="social icon 2" />
                    </div>

                    {activeTab === 'signup' && (
                        <form className="input-group">
                            <div className="input-left">
                                {leftside.map((item, index) => (
                                    <input
                                        key={index}
                                        type={item.type}
                                        className={item.className}
                                        placeholder={item.placeholder}
                                        required
                                    />
                                ))}
                            </div>
                            <div className="input-right">
                                {rightside.map((item, index) => (
                                    <input
                                        key={index}
                                        type={item.type}
                                        className={item.className}
                                        placeholder={item.placeholder}
                                        required
                                    />
                                ))}
                            </div>
                            <button type="submit" className="submit-btnn">Sign up</button>
                        </form>
                    )}

                    {activeTab === 'Log in' && (
                        <form className="input-group">
                            {loginText.map((item, index) => (
                                <input
                                    key={index}
                                    type={item.type}
                                    className={item.className}
                                    placeholder={item.placeholder}
                                    required
                                />
                            ))}
                            <a href="#" className="forget">Forget/Change your password?</a>
                            <button type="submit" className="submit-btnn">Log in</button>
                        </form>
                    )}
                </div>
            </div>
        );
    }
}
